import asyncio
import json
from vuln_scanner.core import ScanEngine
from vuln_scanner.plugins.network_recon import PortScannerPlugin
from vuln_scanner.plugins.http_audit import HTTPHeaderAuditPlugin

async def main():
    # Configuration for plugins
    config = {
        "network": {"ports": [22, 80, 443, 8080], "timeout": 1.5},
        "http": {"timeout": 5}
    }

    # Initialize Engine
    engine = ScanEngine(concurrency_limit=50)

    # Register Plugins
    engine.register_plugin(PortScannerPlugin, config["network"])
    engine.register_plugin(HTTPHeaderAuditPlugin, config["http"])

    # Target to scan
    target = "scanme.nmap.org" # Standard test target

    # Execute Scan
    findings = await engine.scan(target)

    # Output Results as JSON for downstream processing
    output = [
        {
            "plugin": f.plugin_id,
            "severity": f.severity.name,
            "title": f.title,
            "description": f.description,
            "evidence": f.evidence,
            "remediation": f.remediation
        }
        for f in findings
    ]
    
    print("\n--- SCAN REPORT ---")
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        pass